prompt --application/shared_components/plugins/dynamic_action/payroll_rating_popup
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(4129105276436053442)
,p_plugin_type=>'DYNAMIC ACTION'
,p_name=>'PAYROLL_RATING_POPUP'
,p_display_name=>'Payroll Rating Popup'
,p_apexlang_name=>'payrollRatingPopup'
,p_category=>'MISC'
,p_image_prefix=>nvl(wwv_flow_application_install.get_static_plugin_file_prefix('DYNAMIC ACTION','PAYROLL_RATING_POPUP'),'')
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function pay_rat_render (',
'  p_dynamic_action in apex_plugin.t_dynamic_action,',
'  p_plugin         in apex_plugin.t_plugin )',
'return apex_plugin.t_dynamic_action_render_result is',
'/** Rendering Function for APEX Plugin',
unistr('  1.0 - 2018-08-08 - Andr\00E1s T\00F3th - create'),
'*/',
'  c_proc_version constant varchar2(4000 char) := ''1.0'';',
'  c_proc_name constant varchar2(30 char) := ''pay_rat_render'';',
'  c_Debug varchar2(4000 char);',
'  v_ln varchar2(32767 char); v_call_id varchar2(10 char);',
'  l_result apex_plugin.t_dynamic_action_render_result;',
'  v_application_name varchar2(4000 char);',
'  v_timeout varchar2(4000 char); /* integer */',
'  v_check varchar2(4000 char);',
'  v_feature_name varchar2(4000 char);',
'  v_redirect_js varchar2(4000 char);',
'  v_tmp number := 0;',
'begin v_ln := ''0''; v_call_id := trim(to_char(round(dbms_random.value(0,999)),''000''));',
'  v_ln := ''start'';',
'  c_Debug := pcg.c_Debug;',
'  v_ln := ''c_debug string got'';',
'  pcg.log($$PLSQL_UNIT||''.''||c_proc_name,null,c_proc_version,''[''||v_call_id||'',''||v_ln||''] ''||''procedure is called...'', null,c_Debug);',
'  v_ln := ''first debug log done'';',
'  -- Debugging turn on:',
'  IF apex_application.g_debug THEN apex_plugin_util.debug_dynamic_action(p_plugin => p_plugin, p_dynamic_action => p_dynamic_action);',
'    v_ln := ''APEX Debug turned On'';',
'    pcg.log($$PLSQL_UNIT||''.''||c_proc_name,null,c_proc_version,''[''||v_call_id||'',''||v_ln||''] ''||''debug ON'', null,c_Debug);',
'  END IF;',
'  v_ln := ''processing parameters...'';',
'',
'  -- getting parameters',
'  v_application_name := p_dynamic_action.attribute_01;',
'  v_timeout := nvl(p_dynamic_action.attribute_02,''0'');',
'  v_check := nvl(p_dynamic_action.attribute_03,''Y'');',
'  v_feature_name := p_dynamic_action.attribute_04;',
'  v_ln := ''parmas got'';',
'',
'  pcg.log($$PLSQL_UNIT||''.''||c_proc_name,null,c_proc_version,''[''||v_call_id||'',''||v_ln||''] ''||''Parameters: v_application_name=''||v_application_name||'', v_feature_name=''||v_feature_name||'', v_timeout=''||v_timeout||'', v_check=''||v_check, null,c_Debug);',
'  v_ln := ''parameters logged'';',
'',
'  -- Checking if ever submitted a record for this application',
'  if v_check = ''Y'' then',
'    v_ln := ''checking submissions'';',
'    select nvl(max(1),0) into v_tmp from PAY_RAT_USER_RATINGS',
'    where v_application_name = application_name and nvl(v_feature_name,''-1'') = nvl(feature_name,''-1'') and',
'      ( v(''APP_USER'') = submitter or to_char(ora_hash(v(''APP_USER''))) = submitter );',
'    v_ln := ''v_tmp=''||to_char(v_tmp);',
'  end if;',
'  v_ln := ''end checking previous submissions'';',
'',
'  if v_check = ''N'' or v_check = ''Y'' and v_tmp != 1 then',
'    v_ln := ''getting new url'';',
'    -- setting up the URL redirection:',
'    v_redirect_js := APEX_PAGE.GET_URL(',
'      p_application => 31635,',
'      p_page => 601,',
'      p_clear_cache => 601,',
'      p_items => ''P601_APPLICATION_NAME,P601_FEATURE_NAME'',',
'      p_values => v_application_name||'',''||v_feature_name',
'    );',
'',
'    v_ln := ''Attaching JavaScript Library'';',
'    -- Loading attached pay_rat_lib.js file:',
'    apex_javascript.add_library (',
'        p_name      => ''pay_rat_lib'',',
'        p_directory => p_plugin.file_prefix,',
'        p_version   => null );',
'',
'    v_ln := ''adding the function output:'';',
'    -- Setting up the async function call for opening the Popup:',
'    l_result.javascript_function := ''function(){payroll_rating_popup("''||v_redirect_js||''",''||v_timeout||'');}'';',
'    v_ln := ''function calculated'';',
'',
'    pcg.log($$PLSQL_UNIT||''.''||c_proc_name,null,c_proc_version,''[''||v_call_id||'',''||v_ln||''] ''||l_result.javascript_function, null,c_Debug);',
'    v_ln := ''calculated function logged'';',
'',
'  else',
'    v_ln := ''nulling the function'';',
'    l_result.javascript_function := ''function(){return true;}'';',
'    v_ln := ''function nulled'';',
'    pcg.log($$PLSQL_UNIT||''.''||c_proc_name,null,c_proc_version,''[''||v_call_id||'',''||v_ln||''] ''||l_result.javascript_function, null,c_Debug);',
'  end if;',
'  v_ln := ''end big if'';',
'',
'  -- Returning attributes:',
'  l_result.attribute_01 := p_dynamic_action.attribute_01;',
'  l_result.attribute_02 := p_dynamic_action.attribute_02;',
'  l_result.attribute_03 := p_dynamic_action.attribute_03;',
'  l_result.attribute_04 := p_dynamic_action.attribute_04;',
'  v_ln := ''returning other attributes'';',
'',
'  -- ending',
'  return l_result;',
'exception when others then',
'  pcg.log($$PLSQL_UNIT||''.''||c_proc_name,null,c_proc_version,''[''||v_call_id||'',''||v_ln||''] ''||sqlerrm',
'    ||''Parameters: v_application_name=''||v_application_name',
'    ||'', v_feature_name=''||v_feature_name',
'    ||'', v_timeout=''||v_timeout||'', v_check=''||v_check||'', v_tmp=''||to_char(v_tmp)',
'    ||'', v_redirect_js=''||v_redirect_js',
'  ,sqlcode);',
'  raise;',
'end pay_rat_render;',
''))
,p_api_version=>1
,p_render_function=>'pay_rat_render'
,p_substitute_attributes=>true
,p_version_scn=>'1'
,p_subscribe_plugin_settings=>true
,p_version_identifier=>'1.2'
,p_plugin_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'1.0 - Create',
'1.1 - updating javascript calling the url and updating page',
'1.2 - dialog resizing forbidden'))
,p_files_version=>18
);
