,p_process_name=>'After Authentication'
,p_static_id=>'after-authentication'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'-- :G_USER_REGION := pcg.get_region(v(''APP_USER''));',
'select listagg(nvl(trim(substr(role_name,1, instr(role_name,'' '') ) ),''GLOBAL''),'':'') into :G_USER_REGION from MD_USERS_V ',
'    where upper(username) = upper(v(''APP_USER''));',
'',
':G_USER_NAME := pcg.email2name(v(''APP_USER''));',
':G_KPI_LAST_REFRESH := pcg.kv_get_values(''DASH_KPI_LAST_REFRESH'');',
':G_REPORT_LIMIT := pcg.kv_get_values(''DASH_report_fy_limit'');',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>'SH256:fI0B2dXLlqJ5smuwBn6j4vyho2i76hRQuLSsxD34wy4'
,p_updated_on=>wwv_flow_imp.dz('20260923053753Z')
,p_updated_by=>'PRAGYA.KAPOOR@ORACLE.COM'
);
end;
