wwv_flow_imp_page.create_interactive_grid(
 p_id=>wwv_flow_imp.id(10045227553975531482)
,p_internal_uid=>6932980220442543122
,p_is_editable=>false
,p_lazy_loading=>false
,p_requires_filter=>false
,p_select_first_row=>true
,p_fixed_row_height=>true
,p_pagination_type=>'SET'
,p_show_total_row_count=>true
,p_show_toolbar=>true
,p_enable_save_public_report=>false
,p_enable_subscriptions=>true
,p_enable_flashback=>true
,p_define_chart_view=>true
,p_enable_download=>true
,p_download_formats=>'CSV:HTML'
,p_enable_mail_download=>true
,p_fixed_header=>'NONE'
,p_show_icon_view=>false
,p_show_detail_view=>false
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'//  apex.region("IG_Projects").widget().interactiveGrid("getViews", "grid")',
'//  apex.region("IG_Projects").widget().interactiveGrid("option", "config")',
'//',
'function(config)',
'   {',
'   config.defaultGridViewOptions =',
'      {',
'      tooltip:',
'         {',
'         // when the tooltip is integrated with the grid view the content callback',
'         // gets some extra helpful parameters',
'         content: function(callback, model, recordMeta, colMeta, columnDef )',
'            {',
'            var text = null;',
'            if ( columnDef && recordMeta){',
'               // if in/over the notes column put the notes in a tooltip so more of the notes can be seen',
'               // if in/over the name column show the hire date',
'               if ( columnDef.property === "ID" ){text = model.getValue( recordMeta.record, "ID" );}',
'                else if ( columnDef.property === "REGION" ){text = model.getValue( recordMeta.record, "REGION" );}',
'                else if ( columnDef.property === "COUNTRY_ID" ){text = model.getValue( recordMeta.record, "COUNTRY_NAME" );}',
'                else if ( columnDef.property === "COUNTRY_NAME" ){text = model.getValue( recordMeta.record, "COUNTRY_NAME" );}',
'                else if ( columnDef.property === "PERIOD" ){text = model.getValue( recordMeta.record, "PERIOD" );}',
'                else if ( columnDef.property === "ADP_VENDOR_REG" ){text = model.getValue( recordMeta.record, "ADP_VENDOR_REG" );}',
'                else if ( columnDef.property === "ADP_VENDOR_ADDON" ){text = model.getValue( recordMeta.record, "ADP_VENDOR_ADDON" );}',
'                else if ( columnDef.property === "OFF_CYCLE_PAYMENTS" ){text = model.getValue( recordMeta.record, "OFF_CYCLE_PAYMENTS" );}',
'                else if ( columnDef.property === "PAYSLIPS" ){text = model.getValue( recordMeta.record, "PAYSLIPS" );}',
'                else if ( columnDef.property === "CORRECTED_PAYSLIPS" ){text = model.getValue( recordMeta.record, "CORRECTED_PAYSLIPS" );}',
'                else if ( columnDef.property === "PAYMENTS" ){text = model.getValue( recordMeta.record, "PAYMENTS" );}',
'                else if ( columnDef.property === "PAYMENT_PROCESSED" ){text = model.getValue( recordMeta.record, "PAYMENT_PROCESSED" );}',
'                else if ( columnDef.property === "CHANGES" ){text = model.getValue( recordMeta.record, "CHANGES" );}',
'                else if ( columnDef.property === "VENDOR_NAME" ){text = model.getValue( recordMeta.record, "VENDOR_NAME" );}',
'            }',
'            return text;',
'            }',
'         }',
'      };',
'   ',
'   // hidding unwanted features',
'   config.features.flashback = false;',
'   /*config.initActions = function( actions ){',
'      actions.hide("show-aggregate-dialog");',
'      actions.hide("chart-view");',
'   }*/',
'   return config;',
'   }',
''))
);
