wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10744078963745778213)
,p_plug_name=>'HR Headcounts'
,p_static_id=>'hr-headcounts'
,p_parent_plug_id=>wwv_flow_imp.id(11943284945608400836)
,p_region_template_options=>'#DEFAULT#:t-IRR-region--noBorders:js-showMaximizeButton:t-Form--noPadding:margin-left-none:margin-right-none'
,p_escape_on_http_output=>'N'
,p_plug_template=>wwv_flow_imp.id(9729077382463116627)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select *',
'from DASH_HR_HEADCOUNTS_V c',
'where (:P520_REGION like ''%''||c.region||''%''  or trim(:P520_REGION) is null)',
'and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
'and (:P520_SUBREGION like ''%''||c.sub_region||''%'' or trim(:P520_SUBREGION) is null)',
'and (c.id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'--and (:P520_MANAGER like ''%''||pc.manager||''%'' or trim(:P520_MANAGER) is null)',
'--and (:P520_ANALYST like ''%''||pc.reporter||''%'' or trim(:P520_ANALYST) is null)',
'--and (:P520_PERIOD_YEAR like ''%''||trim(substr(pc.period,1,4))||''%'' or trim(:P520_PERIOD_YEAR) is null)',
'--and (:P520_PERIOD_MONTH like ''%''||trim(substr(pc.period,6,2))||''%'' or trim(:P520_PERIOD_MONTH) is null)',
'--and (:P520_VENDOR like ''%''||pc.vendor_name||''%'' or trim(:P520_VENDOR) is null)',
'and (:G_USER_REGION = ''GLOBAL'' or :G_USER_REGION = c.region)',
';'))
,p_plug_source_type=>'NATIVE_IG'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
);
