'//',
'function(config)',
'   {',
'   config.defaultGridViewOptions =',
'      {',
'      tooltip:',
'         {',
'         // when the tooltip is integrated with the grid view the content callback',
'         // gets some extra helpful parameters',
'         content: function(callback, model, recordMeta, colMeta, columnDef )',
'            {',
'            var text = null;',
'            if ( columnDef && recordMeta){',
'               // if in/over the notes column put the notes in a tooltip so more of the notes can be seen',
'               // if in/over the name column show the hire date',
'               if ( columnDef.property === "ID" ){text = model.getValue( recordMeta.record, "ID" );}',
'               else if ( columnDef.property === "REGION" ){text = model.getValue( recordMeta.record, "REGION" );}',
'               else if ( columnDef.property === "COUNTRY_ID" ){text = model.getValue( recordMeta.record, "COUNTRY_NAME" );}',
'               else if ( columnDef.property === "COUNTRY_NAME" ){text = model.getValue( recordMeta.record, "COUNTRY_NAME" );}',
'               else if ( columnDef.property === "PERIOD" ){text = model.getValue( recordMeta.record, "PERIOD" );}',
'               else if ( columnDef.property === "DRAFT_FILE_2_ORACLE_#" ){text = model.getValue( recordMeta.record, "DRAFT_FILE_2_ORACLE_#" );}',
'               else if ( columnDef.property === "DRAFT_FILE_2_VENDOR_#" ){text = model.getValue( recordMeta.record, "DRAFT_FILE_2_VENDOR_#" );}',
'               else if ( columnDef.property === "NORMAL_CYCLE" ){text = model.getValue( recordMeta.record, "NORMAL_CYCLE" );}',
'               else if ( columnDef.property === "ACTUAL_CYCLE" ){text = model.getValue( recordMeta.record, "ACTUAL_CYCLE" );}',
'               else if ( columnDef.property === "DEADLINE_MET_SIGN" ){text = model.getValue( recordMeta.record, "DEADLINE_MET_SIGN" );}',
'               else if ( columnDef.property === "COMMENTS" ){text = model.getValue( recordMeta.record, "COMMENTS" );}',
'               else if ( columnDef.property === "VENDOR_NAME" ){text = model.getValue( recordMeta.record, "VENDOR_NAME" );}',
'               else if ( columnDef.property === "HUB" ){text = model.getValue( recordMeta.record, "HUB" );}',
'               else if ( columnDef.property === "SUB_REGION" ){text = model.getValue( recordMeta.record, "SUB_REGION" );}',
'               else if ( columnDef.property === "COUNTRY_CODE2" ){text = model.getValue( recordMeta.record, "COUNTRY_CODE2" );}',
'               else if ( columnDef.property === "COUNTRY_CODE3" ){text = model.getValue( recordMeta.record, "COUNTRY_CODE3" );}',
'               else if ( columnDef.property === "BRANCH" ){text = model.getValue( recordMeta.record, "BRANCH" );}',
'            }',
'            return text;',
'            }',
'         }',
'      };',
'   ',
'   // hidding unwanted features',
'   config.features.flashback = false;',
'   /*config.initActions = function( actions ){',
'      actions.hide("show-aggregate-dialog");',
