,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(3584491145056298304)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'System Automation - Save Interactive Grid Data'
,p_static_id=>'system-automation-save-interactive-grid-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :ID IS NOT NULL THEN ',
'        -- Update existing record',
'        UPDATE DASH_PAYROLL_AUTOMATIONS ',
'        SET COUNTRY_ID = :COUNTRY_ID, ',
'            PAYROLL = :PAYROLL,',
'            TAA = :TAA, ',
'            TRANSMISSION_INTERFACE = :TRANSMISSION_INTERFACE, ',
'            OSVC = :OSVC, ',
'            DIRECT_DEPOSIT = :DIRECT_DEPOSIT,',
'            EPAYSLIPS = :EPAYSLIPS ',
'        WHERE ID = :ID;',
'    ELSE',
'        -- Insert new record if ID is NULL',
'        INSERT INTO DASH_PAYROLL_AUTOMATIONS (',
'            COUNTRY_ID, ',
'            PAYROLL, ',
'            TAA, ',
'            TRANSMISSION_INTERFACE, ',
'            OSVC, ',
'            DIRECT_DEPOSIT, ',
'            EPAYSLIPS',
'        ) VALUES (',
'            :COUNTRY_ID, ',
'            :PAYROLL, ',
'            :TAA, ',
'            :TRANSMISSION_INTERFACE, ',
'            :OSVC, ',
'            :DIRECT_DEPOSIT, ',
'            :EPAYSLIPS',
'        );',
'    END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>1912419529045617189
);
end;
