wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3522838005435804286)
,p_plug_name=>'MD_EXCHANGE_RATES'
,p_static_id=>'md-exchange-rates'
,p_parent_plug_id=>wwv_flow_imp.id(3522837887516804285)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(9729077382463116627)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select distinct',
'c.company, c.region, c.hub, c.sub_region, c.country, c.branch, c.id as country_id,c.VENDOR_NAME, c.deleted_sign,',
'nvl(c.CURRENCY_CODE3, r.CURRENCY_CODE3) as CURRENCY_CODE3, c.CURRENCY_NAME, r.EX_RATE,r.DATE_START,r.DATE_STOP,',
'r.CREATED,r.CREATED_BY,r.UPDATED,r.UPDATED_BY',
'from md_exchange_rates r',
'full outer join md_countries c',
'on (c.CURRENCY_CODE3 = r.CURRENCY_CODE3)',
'where',
'  (:P520_REGION like ''%''||c.region||''%''  or trim(:P520_REGION) is null)',
'  and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
'  and (:P520_SUBREGION like ''%''||c.sub_region||''%'' or trim(:P520_SUBREGION) is null)',
'  and (c.id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'  --and (:P520_MANAGER like ''%''||r.manager||''%'' or trim(:P520_MANAGER) is null)',
'  and (:P520_ANALYST like ''%''||nvl(r.UPDATED_BY,r.CREATED_BY)||''%'' or trim(:P520_ANALYST) is null)',
'  --and (:P520_PERIOD like ''%''||r.period||''%'' or trim(:P520_PERIOD) is null)',
'  and (:P520_VENDOR like ''%''||c.vendor_name||''%'' or trim(:P520_VENDOR) is null)',
'--   and (:G_USER_REGION = ''GLOBAL'' or :G_USER_REGION = c.region)',
'AND EXISTS (',
'    SELECT 1',
'    FROM TABLE(pcg.string_2_list(:G_USER_REGION, '':'')) user_region',
'    WHERE UPPER(TRIM(user_region.column_value)) = UPPER(c.region)',
'       OR UPPER(TRIM(user_region.column_value)) = ''GLOBAL''',
')',
'',
'',
'',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_updated_on=>wwv_flow_imp.dz('20260923055912Z')
,p_updated_by=>'PRAGYA.KAPOOR@ORACLE.COM'
);
