wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3203152119797935963)
,p_plug_name=>'Security Incidents IG'
,p_static_id=>'security-incidents-ig'
,p_parent_plug_id=>wwv_flow_imp.id(3203151955253935962)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(9729077382463116627)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select i.*,',
'c.REGION,c.HUB,c.SUB_REGION,c.COUNTRY,',
'c.BRANCH, c.VENDOR_NAME,',
'to_char(i.incident_date,''YYYY-MM'') as period',
'from DASH_SECURITY_INCIDENTS i, md_countries c',
'where i.country_id = c.id',
'  and (:P520_REGION like ''%''||c.region||''%''  or trim(:P520_REGION) is null)',
'  and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
'  and (:P520_SUBREGION like ''%''||c.sub_region||''%'' or trim(:P520_SUBREGION) is null)',
'  and (c.id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'  --and (:P520_MANAGER like ''%''||i.manager||''%'' or trim(:P520_MANAGER) is null)',
'  --and (:P520_ANALYST like ''%''||i.reporter||''%'' or trim(:P520_ANALYST) is null)',
'  and (:P520_PERIOD like ''%''||to_char(i.incident_date,''YYYY-MM'')||''%'' or trim(:P520_PERIOD) is null)',
'  and (:P520_VENDOR like ''%''||c.vendor_name||''%'' or trim(:P520_VENDOR) is null)',
'--   and (:G_USER_REGION = ''GLOBAL'' or :G_USER_REGION = c.region)',
'AND EXISTS (',
'    SELECT 1',
'    FROM TABLE(pcg.string_2_list(:G_USER_REGION, '':'')) user_region',
'    WHERE UPPER(TRIM(user_region.column_value)) = UPPER(c.region)',
'       OR UPPER(TRIM(user_region.column_value)) = ''GLOBAL''',
')'))
,p_plug_source_type=>'NATIVE_IG'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_updated_on=>wwv_flow_imp.dz('20260923060700Z')
,p_updated_by=>'PRAGYA.KAPOOR@ORACLE.COM'
);
