,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'  v_managers varchar2(4000 char);',
'  v_manager varchar2(256 char);',
'begin',
'  select min(payroll_manager) into v_managers from md_countries where id = :P50_COUNTRY_ID;',
'  v_manager := null;',
'  for m in (select column_value as manager from table(pcg.string_2_list(v_managers,'':''))) loop',
'    v_manager := nvl(v_manager, m.manager);',
'  end loop;',
'',
'  return v_manager;',
'exception when others then return null;',
'end;'))
