wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(10045229143170531498)
,p_name=>'P51_REGION_SELECTOR'
,p_item_sequence=>140
,p_item_plug_id=>wwv_flow_imp.id(10047138364206458233)
,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare r varchar2(50 char);',
'begin',
'select max(region) into r from md_countries where id = :P51_COUNTRY_ID;',
'return r;',
'end;'))
,p_item_default_type=>'FUNCTION_BODY'
,p_item_default_language=>'PLSQL'
,p_prompt=>'<span style="color: green;">Region</span>'
,p_source_type=>'ALWAYS_NULL'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select region, region r from md_countries c',
'where region is not null  ',
'AND EXISTS (',
'    SELECT 1',
'    FROM TABLE(pcg.string_2_list(:G_USER_REGION, '':'')) user_region',
'    WHERE UPPER(TRIM(user_region.column_value)) = UPPER(c.region)',
'       OR UPPER(TRIM(user_region.column_value)) = ''GLOBAL''',
')',
'-- (region = :G_USER_REGION or :G_USER_REGION = ''GLOBAL'')',
' and region != ''GLOBAL''',
'group by region order by region'))
,p_lov_display_null=>'YES'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(3250656085514507498)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
,p_updated_on=>wwv_flow_imp.dz('20260923110443Z')
,p_updated_by=>'PRAGYA.KAPOOR@ORACLE.COM'
);
