,p_event_result=>'TRUE'
,p_action_sequence=>40
,p_execute_on_page_init=>'Y'
,p_static_id=>'native-execute-plsql-code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_return', 'P51_ADP_VENDOR_REG_MAX,P51_HUB_GROSS_SALARY_AMOUNT_MAX,P51_ADP_VENDOR_ADDON_MAX,P51_HUB_LEAVERS_MAX,P51_OFF_CYCLE_PAYMENTS_MAX,P51_HUB_HIRES_MAX,P51_PAYSLIPS_MAX,P51_HUB_FINAL_HEADCOUNT_MAX,P51_CORRECTED_PAYSLIPS_MAX,P51_PAYMENTS_MAX,P51_PAYMENT_PROC'
||'ESSED_MAX,P51_CHARGES_MAX',
  'items_to_submit', 'P51_COUNTRY_ID,P51_PERIOD',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'select',
    '  max(ADP_VENDOR_REG),',
    '  max(HUB_GROSS_SALARY_AMOUNT),',
    '  max(ADP_VENDOR_ADDON),',
    '  max(HUB_LEAVERS),',
    '  max(OFF_CYCLE_PAYMENTS),',
    '  max(HUB_HIRES),',
    '  max(PAYSLIPS),',
    '  max(HUB_FINAL_HEADCOUNT),',
    '  max(CORRECTED_PAYSLIPS),',
    '  max(PAYMENTS),',
    '  max(PAYMENT_PROCESSED),',
    '  max(CHARGES)',
    'into',
    '  :P51_ADP_VENDOR_REG_MAX,',
    '  :P51_HUB_GROSS_SALARY_AMOUNT_MAX,',
    '  :P51_ADP_VENDOR_ADDON_MAX,',
    '  :P51_HUB_LEAVERS_MAX,',
    '  :P51_OFF_CYCLE_PAYMENTS_MAX,',
    '  :P51_HUB_HIRES_MAX,',
    '  :P51_PAYSLIPS_MAX,',
    '  :P51_HUB_FINAL_HEADCOUNT_MAX,',
    '  :P51_CORRECTED_PAYSLIPS_MAX,',
    '  :P51_PAYMENTS_MAX,',
    '  :P51_PAYMENT_PROCESSED_MAX,',
    '  :P51_CHARGES_MAX',
    'from DASH_PAYROLL_PERIODS',
    'where',
    '  country_id = :P51_COUNTRY_ID and',
    '  period >= trim( to_char(to_number(substr(:P51_PERIOD,1,4))-1) || ''-'' || substr(:P51_PERIOD,6,2) ) and',
    '  period < :P51_PERIOD;')),
  'show_processing', 'Y',
  'suppress_change_event', 'N')).to_clob
,p_wait_for_result=>'Y'
);
