  'items_to_submit', 'P51_COUNTRY_ID,P51_PERIOD',
  'sql_query', wwv_flow_string.join(wwv_flow_t_varchar2(
    'select nvl(max(CORRECTED_PAYSLIPS),0) CORRECTED_PAYSLIPS ',
    'from DASH_PAYROLL_PERIODS ',
    'where',
    '  period = ',
