,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'var corrected_payslips = $(''#P51_CORRECTED_PAYSLIPS'').val()',
    'var variance = $(''#P51_VARIANCE__CORRECTED_PAYSLIPS'').val()',
    'var prev_corrected_payslips = $(''#P51_CORRECTED_PAYSLIPS_PREV'').val()',
    'var threshold = 30',
    'var variance_percentage = (variance / corrected_payslips) * 100',
    'var difference = corrected_payslips - prev_corrected_payslips',
    'var relative_difference = (difference / corrected_payslips) * 100',
    '',
    'if ( variance_percentage > threshold) {',
    '  window.alert(',
    '    ''Warning - please double check the No. of Corrected Payslips.'' + ''\n'' +',
    '    ''Previous No. of Corrected Payslips is '' + prev_corrected_payslips + ''\n'' +',
    '    ''Current No. of Corrected Payslips is '' + corrected_payslips + ''\n'' + ',
    '    ''Difference is '' + difference + '' ('' + (Math.round(relative_difference * 100) / 100) + ''%)'' + ''\n'' +',
    '    ''Variance is '' + variance + '' ('' + (Math.round(variance_percentage * 100) / 100 ) + ''%)''  + ''\n'' +',
    '    ''Variance Threshold is '' + threshold + ''%'' + ''\n''',
    '  )',
    '}',
    '')))).to_clob
);
