wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(3859383693746489182)
,p_event_id=>wwv_flow_imp.id(3859383583241489181)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'var hub_gross_salary_amount = $(''#P66_HUB_GROSS_SALARY_AMOUNT'').val()',
    'var hub_gross_salary_amount_prev = $(''#P66_HUB_GROSS_SALARY_AMOUNT_PREV'').val()',
    'var abs_of_relative_difference = Math.abs( (hub_gross_salary_amount_prev - hub_gross_salary_amount) / hub_gross_salary_amount_prev ) * 100',
    'var threshold = 20',
    'var alertm = ''''',
    'if (abs_of_relative_difference > threshold){',
    '    alertm = (',
    '        ''Warning, please double check the Total Gross Salary for Operations Payroll Staff field.'' + ''\n\n'' +',
    '        ''Current amount is '' + (hub_gross_salary_amount ? hub_gross_salary_amount : 0) + ''\n'' +',
    '        ''Previous month amount is '' + (hub_gross_salary_amount_prev ? hub_gross_salary_amount_prev : 0) + ''\n'' +',
    '        ''Absolute value of Ralative Difference is '' + Math.round(abs_of_relative_difference) + ''%'' + ''\n'' +',
    '        ''Warning threshold is '' + threshold + ''%''',
    '    )',
    '}',
    '',
    'if (hub_gross_salary_amount > (hub_gross_salary_amount_prev * 1.5) ){',
    unistr('  alertm = alertm + ''\005Cn\005CnTotal Gross Salary for Payroll Operations Staff more than 1.5 times higher than versus previous period \2013 please confirm'''),
    '}',
    '',
    'if ( alertm != '''' ){',
    '  window.alert(alertm)',
    '}',
    '')))).to_clob
);
