,p_process_name=>'load'
,p_static_id=>'load'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P66_PERIOD_ID is not null then',
'-- TODO: Security Check b4 loading',
'  select',
'    pcg.get_country_hub(country_id),',
'    country_id,',
'    period,',
'    rejected_trials_due_to_oracle,',
'   -- rejected_trials_due_to_vendor,',
'    payment_delays,',
'    normal_cycle,',
'    hours_saved,',
'    money_saved,',
'    money_recovered,',
'    money_recovered_comments,',
'   -- out_of_scope_changes,',
'  --  out_of_scope_changes_ccy,',
'    hub_gross_salary_amount,',
'    hub_gross_salary_amount_ccy',
'  into',
'    :P66_HUB,',
'    :P66_COUNTRY_ID,',
'    :P66_PERIOD,',
'    :P66_REJECTED_TRIALS_DUE_TO_ORACLE,',
'   -- :P66_REJECTED_TRIALS_DUE_TO_VENDOR,',
'    :P66_PAYMENT_DELAYS,',
'    :P66_NORMAL_CYCLE,',
'    :P66_HOURS_SAVED,',
'    :P66_MONEY_SAVED,',
'    :P66_MONEY_RECOVERED,',
'    :P66_MONEY_RECOVERED_COMMENTS,',
'  --  :P66_OUT_OF_SCOPE_CHANGES,',
'  --  :P66_OUT_OF_SCOPE_CHANGES_CCY,',
'    :P66_HUB_GROSS_SALARY_AMOUNT,',
'    :P66_HUB_GROSS_SALARY_AMOUNT_CCY',
'  from DASH_PERIOD_DETAILS',
'  where id = :P66_PERIOD_ID;',
'end if;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>1597839902802952421
);
wwv_flow_imp_page.create_page_process(
