,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save'
,p_static_id=>'save'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P66_PERIOD_ID is null then',
'-- TODO: Security Check',
'  insert into DASH_PERIOD_DETAILS (',
'    country_id,',
'    period,',
'    rejected_trials_due_to_oracle,',
'   -- rejected_trials_due_to_vendor,',
'    payment_delays,',
'    hours_saved,',
'    money_saved,',
'    money_recovered,',
'    money_recovered_comments,',
'  --  out_of_scope_changes, for sr 133882',
'  --  out_of_scope_changes_ccy,',
'    hub_gross_salary_amount,',
'    hub_gross_salary_amount_ccy,',
'    normal_cycle',
'  ) values (',
'    :P66_COUNTRY_ID,',
'    :P66_PERIOD,',
'    :P66_REJECTED_TRIALS_DUE_TO_ORACLE,',
'   -- :P66_REJECTED_TRIALS_DUE_TO_VENDOR,',
'    :P66_PAYMENT_DELAYS,',
'    :P66_HOURS_SAVED,',
'    :P66_MONEY_SAVED,',
'    :P66_MONEY_RECOVERED,',
'    :P66_MONEY_RECOVERED_COMMENTS,',
'   -- :P66_OUT_OF_SCOPE_CHANGES,',
'   -- :P66_OUT_OF_SCOPE_CHANGES_CCY,',
'    :P66_HUB_GROSS_SALARY_AMOUNT,',
'    :P66_HUB_GROSS_SALARY_AMOUNT_CCY,',
'    :P66_NORMAL_CYCLE',
'  );',
'else',
'  update DASH_PERIOD_DETAILS',
'  set',
'    country_id = :P66_COUNTRY_ID,',
'    period = :P66_PERIOD,',
'    rejected_trials_due_to_oracle = :P66_REJECTED_TRIALS_DUE_TO_ORACLE,',
'    rejected_trials_due_to_vendor = :P66_REJECTED_TRIALS_DUE_TO_VENDOR,',
'    payment_delays = :P66_PAYMENT_DELAYS,',
'    hours_saved = :P66_HOURS_SAVED,',
'    money_saved = :P66_MONEY_SAVED,',
'    money_recovered = :P66_MONEY_RECOVERED,',
'    money_recovered_comments = :P66_MONEY_RECOVERED_COMMENTS,',
'   -- out_of_scope_changes = :P66_OUT_OF_SCOPE_CHANGES,',
'   -- out_of_scope_changes_ccy = :P66_OUT_OF_SCOPE_CHANGES_CCY,',
'    hub_gross_salary_amount = :P66_HUB_GROSS_SALARY_AMOUNT,',
'    hub_gross_salary_amount_ccy = :P66_HUB_GROSS_SALARY_AMOUNT_CCY,',
'    normal_cycle = :P66_NORMAL_CYCLE',
'  where id = :P66_PERIOD_ID;',
'end if;',
'',
'commit;',
''))
