'select c.id country,  r.GENERATOR_ID, k.v as error_generated_by, r.period, count(1) no_of_errors',
'from md_countries c, dash_error_records r, md_kv k ',
'where r.country_id = c.id and k.id = r.generator_id',
'and (:P520_REGION like ''%''||c.region||''%''  or trim(:P520_REGION) is null)',
'and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
