prompt --application/pages/page_00105
begin
wwv_flow_imp_page.create_page(
 p_id=>105
,p_name=>'Error Difference - per Region'
,p_step_title=>'Error Difference'
,p_autocomplete_on_off=>'OFF'
,p_step_template=>wwv_flow_imp.id(9729064735026116592)
,p_page_template_options=>'#DEFAULT#'
,p_required_role=>wwv_flow_imp.id(3267471283812824053)
,p_page_component_map=>'18'
,p_last_updated_on=>wwv_flow_imp.dz('20260923113932Z')
,p_last_updated_by=>'PRAGYA.KAPOOR@ORACLE.COM'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(19480895241213580713)
,p_plug_name=>'Error Difference'
,p_static_id=>'error-difference'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--noBorders:js-showMaximizeButton'
,p_plug_template=>wwv_flow_imp.id(9729077382463116627)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select region, nvl(period_act,period_prev) period,',
'v payroll_process, ',
'CURRENT_ERROR_NUMBER, PREVIOUS_ERROR_NUMBER, ERROR_NUMBER_DIFFERENCE, ERROR_NUMBER_REL_DIFF_PCT,',
'CURRENT_EMPLOYEE_NUM, PREVIOUS_EMPLOYEE_NUM, EMPLOYEE_NUM_DIFFERENCE, EMPLOYEE_NUM_REL_DIFF_PCT',
'from (',
'with errors as',
'(select c.region, r.PROCESS_IMPACT_ID, r.period, count(*) cnt, nvl(sum(r.employee_#_impact),0) sumemp',
'from dash_error_records r, md_countries c',
'where period is not null and country_id is not null and process_impact_id is not null',
'  and c.id = r.country_id',
'  and (:P520_REGION like ''%''||c.region||''%''  or trim(:P520_REGION) is null)',
'  and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
'  and (exists(select 1 from table(pcg.string_2_list(:P520_SUBREGION,'':'')) where column_value = sub_region) or trim(:P520_SUBREGION) is null)',
'  and (c.id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'  and (:P520_MANAGER like ''%''||r.manager||''%'' or trim(:P520_MANAGER) is null)',
'  and (:P520_ANALYST like ''%''||r.reporter||''%'' or trim(:P520_ANALYST) is null)',
'  and (:P520_VENDOR like ''%''||r.vendor_name||''%'' or trim(:P520_VENDOR) is null)',
'--   and (c.region = :G_USER_REGION or :G_USER_REGION = ''GLOBAL'')',
'AND EXISTS (',
'    SELECT 1',
'    FROM TABLE(pcg.string_2_list(:G_USER_REGION, '':'')) user_region',
'    WHERE UPPER(TRIM(user_region.column_value)) = UPPER(c.region)',
'       OR UPPER(TRIM(user_region.column_value)) = ''GLOBAL''',
')',
'group by c.region, r.PROCESS_IMPACT_ID, r.period',
')',
'select ',
'nvl(r.region, rp.region) region, nvl(r.PROCESS_IMPACT_ID,rp.PROCESS_IMPACT_ID) PROCESS_IMPACT_ID,',
'nvl(r.period, case when rp.period is not null then to_char(add_months(to_date(rp.period||''-01'',''YYYY-MM-DD''),+1),''YYYY-MM'') end) period_act, ',
'nvl(rp.period, case when r.period is not null then to_char(add_months(to_date(r.period||''-01'',''YYYY-MM-DD''),-1),''YYYY-MM'') end) period_prev,',
'nvl(r.cnt,0) current_error_number, nvl(rp.cnt,0) previous_error_number, nvl(r.cnt,0) - nvl(rp.cnt,0) error_number_difference, case when nvl(rp.cnt,0)>0 and nvl(r.cnt,0)=0 then -100 when nvl(rp.cnt,0)=0 and nvl(r.cnt,0)>0 then 100 else nvl( ( nvl(r.cn'
||'t,0) - nvl(rp.cnt,0) ) /nullif(nvl(rp.cnt,0),0) ,0)*100 end error_number_rel_diff_pct,',
'nvl(r.sumemp,0) current_employee_num, nvl(rp.sumemp,0) previous_employee_num, nvl(r.sumemp,0) - nvl(rp.sumemp,0) employee_num_difference, case when nvl(rp.sumemp,0)>0 and nvl(r.sumemp,0)=0 then -100 when nvl(rp.sumemp,0)=0 and nvl(r.sumemp,0)>0 then '
||'100 else nvl( ( nvl(r.sumemp,0) - nvl(rp.sumemp,0) ) /nullif(nvl(rp.sumemp,0),0) ,0)*100 end employee_num_rel_diff_pct',
'from errors r',
'full outer join errors rp on (r.period = to_char(add_months(to_date(rp.period||''-01'',''YYYY-MM-DD''),1),''YYYY-MM'') and r.region=rp.region and r.PROCESS_IMPACT_ID = rp.PROCESS_IMPACT_ID)',
') r, md_kv k',
'where k.id = PROCESS_IMPACT_ID and',
'(:P520_PERIOD like ''%''||nvl(period_act,period_prev)||''%'' or trim(:P520_PERIOD) is null);',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>8.5
,p_prn_height=>11
,p_prn_orientation=>'HORIZONTAL'
