wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(3815956525207291204)
,p_chart_id=>wwv_flow_imp.id(11293865602867700509)
,p_static_id=>'payroll-cycle-trials-average'
,p_seq=>40
,p_name=>'Payroll Cycle Trials # Average'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'period,',
'draft_file_avg',
'from (',
'  select rs.period,error_#,employee_sum,draft_file_sum,draft_file_avg,employee_sum_avg,error_#_avg,draft_file_avg_all',
'  from',
'  (select period, count(*) error_#, sum(employee_#_impact) employee_sum from dash_error_records r, md_countries c ',
'    where country_id = c.id',
'      and (:P520_REGION like ''%''||c.region||''%''  or trim(:P520_REGION) is null)',
'      and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
'      and (exists(select 1 from table(pcg.string_2_list(:P520_SUBREGION,'':'')) where column_value = sub_region) or trim(:P520_SUBREGION) is null)',
'      and (c.id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'      and (:P520_MANAGER like ''%''||r.manager||''%'' or trim(:P520_MANAGER) is null)',
'      and (:P520_ANALYST like ''%''||r.reporter||''%'' or trim(:P520_ANALYST) is null)',
'      and (:P520_PERIOD like ''%''||r.period||''%'' or trim(:P520_PERIOD) is null)',
'      and (:P520_VENDOR like ''%''||r.vendor_name||''%'' or trim(:P520_VENDOR) is null)',
'    --   and (c.region = :G_USER_REGION or :G_USER_REGION = ''GLOBAL'')',
'    AND EXISTS (',
'    SELECT 1',
'    FROM TABLE(pcg.string_2_list(:G_USER_REGION, '':'')) user_region',
'    WHERE UPPER(TRIM(user_region.column_value)) = UPPER(c.region)',
'       OR UPPER(TRIM(user_region.column_value)) = ''GLOBAL''',
')',
'    group by period) rs,',
'  (select period, sum( nvl(rejected_trials_due_to_oracle,0) + nvl(rejected_trials_due_to_vendor,0) ) draft_file_sum, ',
'    avg( nullif(nvl(rejected_trials_due_to_oracle,0) + nvl(rejected_trials_due_to_vendor,0),0) ) draft_file_avg from dash_period_details r, md_countries c ',
'    where country_id = c.id',
'      and (:P520_REGION like ''%''||c.region||''%''  or trim(:P520_REGION) is null)',
'      and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
'      and (exists(select 1 from table(pcg.string_2_list(:P520_SUBREGION,'':'')) where column_value = sub_region) or trim(:P520_SUBREGION) is null)',
'      and (c.id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'      --and (:P520_MANAGER like ''%''||r.manager||''%'' or trim(:P520_MANAGER) is null)',
'      and (:P520_ANALYST like ''%''||r.reporter||''%'' or trim(:P520_ANALYST) is null)',
'      and (:P520_PERIOD like ''%''||r.period||''%'' or trim(:P520_PERIOD) is null)',
'      and (:P520_VENDOR like ''%''||c.vendor_name||''%'' or trim(:P520_VENDOR) is null)',
'    --   and (c.region = :G_USER_REGION or :G_USER_REGION = ''GLOBAL'')',
'    AND EXISTS (',
'    SELECT 1',
'    FROM TABLE(pcg.string_2_list(:G_USER_REGION, '':'')) user_region',
'    WHERE UPPER(TRIM(user_region.column_value)) = UPPER(c.region)',
'       OR UPPER(TRIM(user_region.column_value)) = ''GLOBAL''',
')',
'    group by period) cs,',
'  (select avg(nullif(employee_sum,0)) employee_sum_avg, avg(nullif(error_#,0)) error_#_avg ',
'    from (select sum(employee_#_impact) employee_sum, count(*) error_# from dash_error_records r, md_countries c ',
'    where country_id = c.id',
'      and (:P520_REGION like ''%''||c.region||''%''  or trim(:P520_REGION) is null)',
'      and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
'      and (exists(select 1 from table(pcg.string_2_list(:P520_SUBREGION,'':'')) where column_value = sub_region) or trim(:P520_SUBREGION) is null)',
'      and (c.id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'      and (:P520_MANAGER like ''%''||r.manager||''%'' or trim(:P520_MANAGER) is null)',
'      and (:P520_ANALYST like ''%''||r.reporter||''%'' or trim(:P520_ANALYST) is null)',
'      and (:P520_PERIOD like ''%''||r.period||''%'' or trim(:P520_PERIOD) is null)',
'      and (:P520_VENDOR like ''%''||r.vendor_name||''%'' or trim(:P520_VENDOR) is null)',
'    --   and (c.region = :G_USER_REGION or :G_USER_REGION = ''GLOBAL'')',
'    AND EXISTS (',
'    SELECT 1',
'    FROM TABLE(pcg.string_2_list(:G_USER_REGION, '':'')) user_region',
'    WHERE UPPER(TRIM(user_region.column_value)) = UPPER(c.region)',
'       OR UPPER(TRIM(user_region.column_value)) = ''GLOBAL''',
')',
'    group by period) ) all_err_avg,',
'  (select avg( nullif( nvl(rejected_trials_due_to_oracle,0) + nvl(rejected_trials_due_to_vendor,0) ,0) ) draft_file_avg_all from dash_period_details r, md_countries c ',
'    where country_id = c.id',
'      and (:P520_REGION like ''%''||c.region||''%''  or trim(:P520_REGION) is null)',
'      and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
'      and (exists(select 1 from table(pcg.string_2_list(:P520_SUBREGION,'':'')) where column_value = sub_region) or trim(:P520_SUBREGION) is null)',
'      and (c.id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'      --and (:P520_MANAGER like ''%''||r.manager||''%'' or trim(:P520_MANAGER) is null)',
'      and (:P520_ANALYST like ''%''||r.reporter||''%'' or trim(:P520_ANALYST) is null)',
'      and (:P520_PERIOD like ''%''||r.period||''%'' or trim(:P520_PERIOD) is null)',
'      and (:P520_VENDOR like ''%''||c.vendor_name||''%'' or trim(:P520_VENDOR) is null)',
'    --   and (c.region = :G_USER_REGION or :G_USER_REGION = ''GLOBAL'')',
'    AND EXISTS (',
'    SELECT 1',
'    FROM TABLE(pcg.string_2_list(:G_USER_REGION, '':'')) user_region',
'    WHERE UPPER(TRIM(user_region.column_value)) = UPPER(c.region)',
'       OR UPPER(TRIM(user_region.column_value)) = ''GLOBAL''',
')',
'  ) full_cyc_avg',
'  where rs.period=cs.period',
')',
'order by 1 desc;',
'',
''))
,p_series_type=>'line'
,p_items_value_column_name=>'DRAFT_FILE_AVG'
,p_items_label_column_name=>'PERIOD'
,p_line_style=>'solid'
,p_line_type=>'auto'
,p_marker_rendered=>'auto'
,p_marker_shape=>'auto'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>false
,p_threshold_display=>'onIndicator'
,p_updated_on=>wwv_flow_imp.dz('20260923120053Z')
,p_updated_by=>'PRAGYA.KAPOOR@ORACLE.COM'
);
