 p_id=>wwv_flow_imp.id(3584490075889298293)
,p_plug_name=>'Training Hours/FTE'
,p_static_id=>'training-hours-fte'
,p_region_template_options=>'#DEFAULT#:js-showMaximizeButton:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(9729077861327116628)
,p_plug_display_sequence=>40
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select t.period, kpi_value as training_hours, nvl(c.region,c.company) country',
'from',
'(select',
'  pcg.get_country_region_id(country_id) country_id,',
'  sum(training_hours) / nullif(sum(trained_employees_num),0) kpi_value,',
'  period',
'from DASH_HUB_TRAININGS',
'group by pcg.get_country_region_id(country_id), period',
'union all',
'select',
'  pcg.get_country_company_id(''Oracle'') country_id,',
'  sum(training_hours) / nullif(sum(trained_employees_num),0) kpi_value,',
'  period',
'from DASH_HUB_TRAININGS',
'group by period) t,',
'md_countries c',
'where',
'c.id = t.country_id',
'and (:P520_REGION like ''%''||c.region||''%''  or trim(:P520_REGION) is null)',
'and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
'and (:P520_PERIOD like ''%''||t.period||''%'' or trim(:P520_PERIOD) is null)',
'-- and (:G_USER_REGION = ''GLOBAL'' or :G_USER_REGION = c.region)',
'AND EXISTS (',
'    SELECT 1',
'    FROM TABLE(pcg.string_2_list(:G_USER_REGION, '':'')) user_region',
'    WHERE UPPER(TRIM(user_region.column_value)) = UPPER(c.region)',
'       OR UPPER(TRIM(user_region.column_value)) = ''GLOBAL''',
')'))
,p_plug_source_type=>'NATIVE_JET_CHART'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_plug_query_num_rows=>15
,p_updated_on=>wwv_flow_imp.dz('20260923120454Z')
,p_updated_by=>'PRAGYA.KAPOOR@ORACLE.COM'
);
