 p_id=>wwv_flow_imp.id(3485981640076934371)
,p_name=>'KPI Cards'
,p_static_id=>'kpi-cards'
,p_template=>wwv_flow_imp.id(9729077861327116628)
,p_display_sequence=>50
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_template_options=>'#DEFAULT#:js-showMaximizeButton:t-Region--accent1:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Cards--displaySubtitle:t-Cards--featured force-fa-lg:t-Cards--displayInitials:t-Cards--5cols:t-Cards--hideBody:t-Cards--iconsRounded:t-Cards--animColorFill:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'  GOAL_CATEGORY,',
'  KPI_NAME as card_title,',
'  dash_pkg.card_initial_kpi_value_tags(KPI_VALUE, UNIT) as card_initials,',
'  dash_pkg.target_previous_tags(KPI_GOAL,KPI_VALUE_PREVIOUS) as card_subtitle,',
'  KPI_VALUE_COLOR as card_color,',
'  COUNTRY_ID',
'from DASH_REPORTS o',
'where period = :P109_TERM',
'and country_id = :P109_COUNTRY_ID',
'and (',
'  :P109_GOAL_CATEGORY is null or GOAL_CATEGORY in ( select column_value from table(pcg.string_2_list(:P109_GOAL_CATEGORY,'':'')) ) ',
') and',
'    (:P520_REGION like ''%''||region||''%''  or trim(:P520_REGION) is null)',
'    and (:P520_HUB like ''%''||hub||''%'' or trim(:P520_HUB) is null)',
'    and (exists(select 1 from table(pcg.string_2_list(:P520_SUBREGION,'':'')) where column_value = sub_region) or trim(:P520_SUBREGION) is null)',
'    and (country_id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'    and (:P520_PERIOD like ''%''||period||''%'' or trim(:P520_PERIOD) is null)',
'and (',
'  upper(o.GOAL_CATEGORY) not like ''%COST%'' or',
'  (',
'    (DASH_PKG.is_Payroll_Manager(:APP_USER) = ''Y'' and nvl(eat_pkg.get_m_level(:APP_USER), 0) > 3) or',
'    DASH_PKG.is_Operations(:APP_USER) = ''Y'' or',
'    DASH_PKG.is_Admin(:APP_USER) = ''Y'' or',
'    DASH_PKG.is_Director(:APP_USER) = ''Y''',
'  )',
')',
'order by 1, 2',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P109_TERM,P109_COUNTRY_ID,P109_GOAL_CATEGORY'
,p_fixed_header=>'PAGE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(9729085076057116642)
,p_query_num_rows=>70
