wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3743730765851882384)
,p_plug_name=>'KPI FY Charts'
,p_static_id=>'kpi-fy-charts'
,p_region_name=>'KPI_FY_CHART'
,p_region_template_options=>'#DEFAULT#:js-showMaximizeButton:t-Region--accent1:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(9729077861327116628)
,p_plug_display_sequence=>70
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with cids as (',
'    select country, country_id from (',
'        select pcg.get_country_hub(pcg.get_country_hub_id(hub)) country, pcg.get_country_hub_id(hub) country_id from (select distinct hub from md_countries where :P109_LEVEL=''Hub'' and hub is not null and ''GLOBAL_HUB'' != hub) union all',
'        select country||case when branch is not null then '' - ''||branch end country, id as country_id from md_countries where :P109_LEVEL=''Country'' and Country is not null and :P109_HUB_FILTER like ''%''||hub||''%'' union all',
'        select pcg.get_country_region(pcg.get_country_region_id(region)) country, pcg.get_country_region_id(region) country_id from (select distinct region from md_countries where :P109_LEVEL=''Region'' and region is not null and ''GLOBAL'' !=region) uni'
||'on all',
'        select pcg.get_country_company(pcg.get_country_company_id(''Oracle'')) country, pcg.get_country_company_id(''Oracle'') country_id from dual',
'    )',
')',
'select',
'    c.period,',
'    replace(c.country,''Oracle'', '' Oracle '') country,',
'    o.KPI_VALUE',
'from',
'    (select period, kpi_value, country_id from DASH_REPORTS where KPI_ID = :P109_KPI_ID_CHRT_2 and period like ''FY%'' and country_id in (select country_id from cids) ',
'          and (:P520_REGION like ''%''||region||''%''  or trim(:P520_REGION) is null)',
'          and (:P520_HUB like ''%''||hub||''%'' or trim(:P520_HUB) is null)',
'          and (exists(select 1 from table(pcg.string_2_list(:P520_SUBREGION,'':'')) where column_value = sub_region) or trim(:P520_SUBREGION) is null)',
'          and (country_id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'          and (:P520_PERIOD like ''%''||period||''%'' or trim(:P520_PERIOD) is null)',
'      and (',
'        upper(GOAL_CATEGORY) not like ''%COST%'' or',
'        (',
'          (DASH_PKG.is_Payroll_Manager(:APP_USER) = ''Y'' and nvl(eat_pkg.get_m_level(:APP_USER), 0) > 3) or',
'          DASH_PKG.is_Operations(:APP_USER) = ''Y'' or',
'          DASH_PKG.is_Admin(:APP_USER) = ''Y'' or',
'          DASH_PKG.is_Director(:APP_USER) = ''Y''',
'        )',
'      )',
'    ) o',
'    right outer join',
'    (',
'        select country, country_id, period from',
'        cids,',
'        (select distinct dash_pkg.period_2_term(period) period from dash_periods_v where (:P520_PERIOD like ''%''||period||''%'' or trim(:P520_PERIOD) is null))',
'    ) c',
'    on c.country_id = o.country_id and c.period = o.period',
'where :G_REPORT_LIMIT <= dash_pkg.period_2_term(c.period)',
'order by period, country'))
,p_plug_source_type=>'NATIVE_JET_CHART'
,p_ajax_items_to_submit=>'P109_KPI_ID_CHRT_2,P109_LEVEL,P109_HUB_FILTER'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_plug_query_num_rows=>15
);
