wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3486117979341798766)
,p_plug_name=>'KPI Monthly Charts'
,p_static_id=>'kpi-monthly-charts'
,p_region_template_options=>'#DEFAULT#:js-showMaximizeButton:t-Region--accent1:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(9729077861327116628)
,p_plug_display_sequence=>60
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'  dash_pkg.period_2_term(year||''-''||month) as year, ',
'  dash_pkg.period_2_fiscalmonth(year||''-''||month) as month, ',
'  KPI_VALUE',
'  , year as myyear',
'  , month as mymonth',
'from (',
'  select nvl(p.year,d.year) year,nvl(p.month,d.month) month, kpi_value from',
'  (',
'    select',
'      substr(period,1,4) as year,',
'      substr(period,6,2) as month,',
'      KPI_VALUE',
'    from DASH_REPORTS o',
'    where ',
'      KPI_ID = :P109_KPI_ID_CHRT and ',
'      country_id = :P109_COUNTRY_ID_CHRT and',
'      period not like ''FY%''',
'      and',
'          (:P520_REGION like ''%''||region||''%''  or trim(:P520_REGION) is null)',
'          and (:P520_HUB like ''%''||hub||''%'' or trim(:P520_HUB) is null)',
'          and (exists(select 1 from table(pcg.string_2_list(:P520_SUBREGION,'':'')) where column_value = sub_region) or trim(:P520_SUBREGION) is null)',
'          and (country_id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'          and (:P520_PERIOD like ''%''||period||''%'' or trim(:P520_PERIOD) is null)',
'      and (',
'        upper(o.GOAL_CATEGORY) not like ''%COST%'' or',
'        (',
'          (DASH_PKG.is_Payroll_Manager(:APP_USER) = ''Y'' and nvl(eat_pkg.get_m_level(:APP_USER), 0) > 3) or',
'          DASH_PKG.is_Operations(:APP_USER) = ''Y'' or',
'          DASH_PKG.is_Admin(:APP_USER) = ''Y'' or',
'          DASH_PKG.is_Director(:APP_USER) = ''Y''',
'        )',
'      )',
'  ) d',
'  full outer join',
'  (',
'    select y year, m month from dash_periods_v where (:P520_PERIOD like ''%''||period||''%'' or trim(:P520_PERIOD) is null)',
'  ) p',
'  on',
'    (p.year = d.year and p.month = d.month)',
') ',
'where :G_REPORT_LIMIT <= dash_pkg.period_2_term(year||''-''||month)',
'order by year asc, month asc'))
,p_plug_source_type=>'NATIVE_JET_CHART'
,p_ajax_items_to_submit=>'P109_COUNTRY_ID_CHRT,P109_KPI_ID_CHRT'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_plug_query_num_rows=>15
);
