wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3247954150823577789)
,p_plug_name=>'KPI Raw Report IG'
,p_static_id=>'kpi-raw-report-ig'
,p_region_name=>'RAW_REPORT'
,p_parent_plug_id=>wwv_flow_imp.id(3743709704439882373)
,p_icon_css_classes=>'fa-table'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:js-showMaximizeButton:t-Region--showIcon:t-Region--scrollBody'
,p_escape_on_http_output=>'N'
,p_plug_template=>wwv_flow_imp.id(9729077861327116628)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'  r.SEQ_ID,',
'  r.KPI_ID,',
'  r.COUNTRY_ID,',
'  round(r.KPI_VALUE, 1) KPI_VALUE,',
'  r.KPI_GOAL,',
'  r.PERIOD,',
'  r.REGION,',
'  r.HUB,',
'  r.SUB_REGION,',
'  r.COUNTRY,',
'  r.BRANCH,',
'  r.KPI_NAME,',
'  r.UNIT,',
'  r.GOAL_TERM,',
'  r.GOAL_CATEGORY,',
'  r.KPI_GOAL_PREVIOUS,',
'  r.KPI_VALUE_COLOR,',
'  round(r.KPI_VALUE_PREVIOUS, 1) KPI_VALUE_PREVIOUS, ',
'  round(r.KPI_VALUE - r.KPI_VALUE_PREVIOUS, 1) difference, ',
'  round(((r.KPI_VALUE - r.KPI_VALUE_PREVIOUS) / nullif(r.KPI_VALUE_PREVIOUS,0)) * 100, 1) relative_difference_percentage,',
'  round((r.KPI_VALUE - r.KPI_VALUE_PREVIOUS) / 2, 1) mean_of_kpis,',
'  round((',
'    power(r.KPI_VALUE - ((r.KPI_VALUE - r.KPI_VALUE_PREVIOUS) / 2), 2) +',
'    power(r.KPI_VALUE_PREVIOUS - ((r.KPI_VALUE - r.KPI_VALUE_PREVIOUS) / 2), 2)',
'  ) / 2, 1) as variance_of_kpis',
'from DASH_REPORTS r',
'where',
'    (:P520_REGION like ''%''||region||''%''  or trim(:P520_REGION) is null)',
'    and (:P520_HUB like ''%''||hub||''%'' or trim(:P520_HUB) is null)',
'    and (exists(select 1 from table(pcg.string_2_list(:P520_SUBREGION,'':'')) where column_value = sub_region) or trim(:P520_SUBREGION) is null)',
'    and (country_id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'    and (:P520_PERIOD like ''%''||period||''%'' or trim(:P520_PERIOD) is null)',
'    and :G_REPORT_LIMIT <= dash_pkg.period_2_term(r.period)',
'    and (',
'      upper(r.GOAL_CATEGORY) not like ''%COST%'' or',
'      (',
'        (DASH_PKG.is_Payroll_Manager(:APP_USER) = ''Y'' and nvl(eat_pkg.get_m_level(:APP_USER), 0) > 3) or',
'        DASH_PKG.is_Operations(:APP_USER) = ''Y'' or',
'        DASH_PKG.is_Admin(:APP_USER) = ''Y'' or',
'        DASH_PKG.is_Director(:APP_USER) = ''Y''',
'      )',
'    )',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
);
