wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3873134075530163310)
,p_plug_name=>'GPAT Records per Period  IG'
,p_static_id=>'gpat-records-per-period-ig'
,p_parent_plug_id=>wwv_flow_imp.id(3873134018080163309)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(9729077382463116627)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with',
'  periods as (',
'    select :P113_PERIOD as period from dual where :P113_PERIOD is not null',
'  ),',
'  entities as (',
'    select',
'      ea.ID_ENTITY, ea.ENTITY_NAME, ea.COUNTRY_ID2 as COUNTRY_ID, c.REGION, c.COUNTRY',
'    from MD_ENTITIES ea inner join MD_COUNTRIES c on c.id = ea.COUNTRY_ID2',
'    where (:P520_REGION like ''%''||c.region||''%'' or trim(:P520_REGION) is null)',
'      and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
'      and (exists(select 1 from table(pcg.string_2_list(:P520_SUBREGION,'':'')) where column_value = sub_region) or trim(:P520_SUBREGION) is null)',
'      and (c.id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'    --   and (c.region = :G_USER_REGION or :G_USER_REGION = ''GLOBAL'')',
'    AND EXISTS (',
'    SELECT 1',
'    FROM TABLE(pcg.string_2_list(:G_USER_REGION, '':'')) user_region',
'    WHERE UPPER(TRIM(user_region.column_value)) = UPPER(c.region)',
'       OR UPPER(TRIM(user_region.column_value)) = ''GLOBAL''',
')',
'  ),',
'  paymenttypes as (',
'    select ''Interim/Other'' type_name from dual union select ''Regular'' type_name from dual',
'  ),',
'  periodsentities as (',
'    select * from periods, entities, paymenttypes',
'  ),',
'  gpatd as (',
'    select ma.ID_GPAT, to_char(ma.PAY_DATE,''YYYY-MM'') period, ma.ENTITY_ID, case pa.name when ''Regular'' then ''Regular'' else ''Interim/Other'' end type_name',
'    from GPAT_MAIN ma inner join GPAT_PAYMENT_TYPE pa on ma.APPROVAL_STATUS = ''Approved'' and ma.PAYMENT_TYPE_ID = pa.ID_PAYMENT_TYPE and pa.name in (''Regular'', ''Interim'')',
'  )',
'select',
'  COUNTRY, ENTITY_NAME, ID_ENTITY, ENTITY_DISPLAY_NAME',
'  , sum(case TYPE_NAME when ''Regular'' then CNT else 0 end) "Regular"',
'  , sum(case TYPE_NAME when ''Interim/Other'' then CNT else 0 end) "Interim/Other"',
'from (',
'  select',
'      cep.COUNTRY, cep.ENTITY_NAME, cep.ID_ENTITY',
'      , cep.COUNTRY || '' - '' || cep.ENTITY_NAME || '' (''||to_char(cep.ID_ENTITY)||'')'' as ENTITY_DISPLAY_NAME',
'      , cep.TYPE_NAME',
'      , sum(case when d.ID_GPAT is not null then 1 else 0 end) as CNT',
'    from',
'      periodsentities cep',
'      left outer join gpatd d on d.ENTITY_ID = cep.ID_ENTITY and d.PERIOD = cep.PERIOD and d.TYPE_NAME = cep.TYPE_NAME',
'    where cep.period = :P113_PERIOD',
'    group by',
'       cep.ID_ENTITY, cep.COUNTRY, cep.ENTITY_NAME, cep.TYPE_NAME',
')',
'group by COUNTRY, ENTITY_NAME, ID_ENTITY, ENTITY_NAME, ENTITY_DISPLAY_NAME;'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P113_PERIOD'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'GPAT Records per Period  IG'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
