wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3873131874168163288)
,p_plug_name=>'GPAT Regular Cycles # IG'
,p_static_id=>'gpat-regular-cycles-ig'
,p_parent_plug_id=>wwv_flow_imp.id(3873133828654163307)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(9729077382463116627)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with',
'  periods as (',
'    select period from dash_periods_v where :P520_PERIOD like ''%''||period||''%'' or trim(:P520_PERIOD) is null',
'  ),',
'  entities as (',
'    select',
'      ea.ID_ENTITY, ea.ENTITY_NAME, ea.COUNTRY_ID2 as COUNTRY_ID, c.REGION, c.HUB, c.SUB_REGION,',
'      c.COUNTRY, c.COUNTRY_CODE2, c.COUNTRY_CODE3, c.BRANCH, c.PAYROLL_MANAGER, c.VENDOR_NAME, c.CURRENCY_NAME,',
'      c.COUNTRY_GEO',
'    from MD_ENTITIES ea inner join MD_COUNTRIES c on c.id = ea.COUNTRY_ID2',
'    where (:P520_REGION like ''%''||c.region||''%'' or trim(:P520_REGION) is null)',
'      and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
'      and (exists(select 1 from table(pcg.string_2_list(:P520_SUBREGION,'':'')) where column_value = sub_region) or trim(:P520_SUBREGION) is null)',
'      and (c.id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'    --   and (c.region = :G_USER_REGION or :G_USER_REGION = ''GLOBAL'')',
'    AND EXISTS (',
'    SELECT 1',
'    FROM TABLE(pcg.string_2_list(:G_USER_REGION, '':'')) user_region',
'    WHERE UPPER(TRIM(user_region.column_value)) = UPPER(c.region)',
'       OR UPPER(TRIM(user_region.column_value)) = ''GLOBAL''',
')',
'  ),',
'  paymenttypes as (',
'    select ''Interim/Other'' type_name from dual union select ''Regular'' type_name from dual',
'  ),',
'  periodsentities as (',
'    select * from periods, entities, paymenttypes',
'  ),',
'  gpatd as (',
'    select ma.ID_GPAT, to_char(ma.PAY_DATE,''YYYY-MM'') period, ma.ENTITY_ID, case pa.name when ''Regular'' then ''Regular'' else ''Interim/Other'' end type_name',
'    from GPAT_MAIN ma inner join GPAT_PAYMENT_TYPE pa on ma.APPROVAL_STATUS = ''Approved'' and ma.PAYMENT_TYPE_ID = pa.ID_PAYMENT_TYPE and pa.name in (''Regular'', ''Interim'')',
'  )',
'select',
'    cep.ID_ENTITY, cep.ENTITY_NAME',
'    --, cep.COUNTRY_GEO',
'    , cep.COUNTRY_ID, cep.BRANCH, cep.COUNTRY, cep.COUNTRY_CODE2, cep.COUNTRY_CODE3, cep.PAYROLL_MANAGER, cep.VENDOR_NAME, cep.CURRENCY_NAME, cep.SUB_REGION, cep.HUB, cep.REGION',
'    , cep.PERIOD',
'    , cep.TYPE_NAME',
'    , d.ID_GPAT',
'    , case when d.ID_GPAT is not null then 1 else 0 end as CNT',
'  from',
'    periodsentities cep',
'    left outer join gpatd d on d.ENTITY_ID = cep.ID_ENTITY and d.PERIOD = cep.PERIOD and d.TYPE_NAME = cep.TYPE_NAME',
'  /*order by cep.ID_ENTITY, cep.period, cep.type_name*/',
';'))
,p_plug_source_type=>'NATIVE_IG'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
