wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(3819665045717499079)
,p_name=>'Errors Records'
,p_static_id=>'errors-records-2'
,p_region_name=>'ERRORS'
,p_template=>wwv_flow_imp.id(9729077861327116628)
,p_display_sequence=>100
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_template_options=>'#DEFAULT#:t-Region--accent3:t-Region--noBorder:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select * from(',
'select',
'   country_id,',
'   pcg.get_country_region(country_id) region,',
'   pcg.get_country_hub(country_id) hub,',
'   pcg.get_country_subregion(country_id) subregion,',
'   pcg.get_country_name_branch_c(country_id) country_name,',
'   replace(XMLELEMENT("div", datas).getclobval(),''&amp;'',''&'') dtable',
'from',
'(',
'  select',
'    country_id,',
'    xmlagg(',
'        case',
'            when nvl(cnt,0) = 0 then XMLELEMENT("div", xmlattributes(''toth_fw'' as "class", ''background-color: #ccff99;'' as "style", period as "title"), ''&nbsp;'' )',
'            when nvl(cnt,0) <> 0 then XMLELEMENT("div", xmlattributes(''toth_fw'' as "class", period as "title"), to_char(cnt) )',
'            else null',
'        end',
'    order by period) ',
'    datas',
'  from',
'  (',
'    select',
'      ps.period,',
'      ps.country_id,',
'      d.cnt',
'    from',
'    (',
'      select period,country_id,count(id) cnt from DASH_ERROR_RECORDS group by period,country_id order by 2',
'    ) d,',
'    (',
'      select p.period, c.id country_id from DASH_PERIODS_V p, md_countries c where',
'            (:P520_REGION like ''%''||c.region||''%''  or trim(:P520_REGION) is null)',
'        and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
'        and (:P520_SUBREGION like ''%''||c.sub_region||''%'' or trim(:P520_SUBREGION) is null)',
'        and (c.id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'        and (:P520_PERIOD like ''%''||p.period||''%'' or trim(:P520_PERIOD) is null)',
'        -- and (c.region = :G_USER_REGION or :G_USER_REGION = ''GLOBAL'')',
'        AND EXISTS (',
'    SELECT 1',
'    FROM TABLE(pcg.string_2_list(:G_USER_REGION, '':'')) user_region',
'    WHERE UPPER(TRIM(user_region.column_value)) = UPPER(c.region)',
'       OR UPPER(TRIM(user_region.column_value)) = ''GLOBAL''',
')',
'        and c.region is not null',
'    ) ps',
'    where ps.country_id = d.country_id (+) and ps.period = d.period (+)',
'  ) group by country_id',
') order by',
'case when nvl(pcg.get_country_region(country_id),''GLOBAL'') = ''GLOBAL'' then ''0'' end||',
'pcg.get_country_region(country_id)||',
'pcg.get_country_hub(country_id)||',
'pcg.get_country_subregion(country_id)||',
'pcg.get_country_name_branch(country_id)',
')'))
,p_display_condition_type=>'NEVER'
,p_read_only_when_type=>'ALWAYS'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(9729087849617116647)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_show_nulls_as=>'-'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_updated_on=>wwv_flow_imp.dz('20260923125625Z')
,p_updated_by=>'PRAGYA.KAPOOR@ORACLE.COM'
);
