wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3822727337289044276)
,p_plug_name=>'Errors Records - &P150_FISCAL_YEAR.'
,p_static_id=>'errors-records-p150-fiscal-year'
,p_region_template_options=>'#DEFAULT#:js-showMaximizeButton:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(9729077861327116628)
,p_plug_display_sequence=>40
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Errors Records',
'with datatable as (',
'select',
'  d.period,',
'  trim(substr(dash_pkg.period_2_fiscalmonth(d.period),3,100)) month_name,',
'  to_number(substr(dash_pkg.period_2_fiscalmonth(d.period),1,2)) fiscal_month_number,',
'  d.country_id,',
'  c.country country_name,',
'  c.branch,',
'  c.sub_region,',
'  c.hub,',
'  c.region,',
'  count(d.id) cnt',
'from',
'  (',
'    select nvl(p.period, pd.period) period, nvl(p.country_id, pd.country_id) country_id, pd.id',
'    from DASH_ERROR_RECORDS pd',
'    full outer join',
'      (select distinct pv.period, cl.id country_id from dash_periods_v pv, md_countries cl) p',
'    on (p.period = pd.period and p.country_id = pd.country_id)',
'    where',
'      dash_pkg.period_2_term(nvl(p.period, pd.period)) = :P150_FISCAL_YEAR',
'  ) d,',
'  md_countries c',
'where c.id = d.country_id',
'--   and (c.region = :G_USER_REGION or :G_USER_REGION = ''GLOBAL'')',
'AND EXISTS (',
'    SELECT 1',
'    FROM TABLE(pcg.string_2_list(:G_USER_REGION, '':'')) user_region',
'    WHERE UPPER(TRIM(user_region.column_value)) = UPPER(c.region)',
'       OR UPPER(TRIM(user_region.column_value)) = ''GLOBAL''',
')',
'  and (:P520_REGION like ''%''||c.region||''%''  or trim(:P520_REGION) is null)',
'  and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
'  and (:P520_SUBREGION like ''%''||c.sub_region||''%'' or trim(:P520_SUBREGION) is null)',
'  and (c.id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'group by d.period, d.country_id, c.branch, c.country, c.sub_region, c.hub, c.region',
')',
'select * from (',
'  select month_name, country_id, country_name, branch, sub_region, hub, region, cnt from datatable i',
') pivot (',
'  sum(cnt)',
'  for month_name',
'  in (''Jun'' "06",''Jul'' "07",''Aug'' "08",''Sep'' "09",''Oct'' "10",''Nov'' "11",''Dec'' "12",''Jan'' "01",''Feb'' "02",''Mar'' "03",''Apr'' "04",''May'' "05")',
')'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P150_FISCAL_YEAR'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_updated_on=>wwv_flow_imp.dz('20260923125625Z')
,p_updated_by=>'PRAGYA.KAPOOR@ORACLE.COM'
);
