wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3333461762554194184)
,p_plug_name=>'Payroll Cycles'
,p_static_id=>'payroll-cycles'
,p_region_name=>'CYCLES'
,p_region_template_options=>'#DEFAULT#:t-Region--accent2:t-Region--noBorder:t-Region--scrollBody'
,p_escape_on_http_output=>'N'
,p_plug_template=>wwv_flow_imp.id(9729077861327116628)
,p_plug_display_sequence=>80
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'   country_id,',
'   pcg.get_country_region(country_id) region,',
'   pcg.get_country_hub(country_id) hub,',
'   pcg.get_country_subregion(country_id) subregion,',
'   pcg.get_country_name_branch_c(country_id) country_name,',
'   ''<div>''||datas||''</div>'' dtable',
'from',
'(',
'  select',
'    country_id,',
'    listagg(',
'      case',
'        when nvl(cnt,0) = 0 then ''<div class="toth_fw" style="background-color: #ffb399;" title="''||period||''">&nbsp;</div>''',
'        when cnt = 1        then ''<div class="toth_fw" style="background-color: #ccff99;" title="''||period||''">1</div>''',
'        when cnt > 1        then ''<div class="toth_fw" style="background-color: #ffba66;" title="''||period||''">''||to_char(cnt)||''</div>''',
'        else ''<div class="toth_fw" style="background-color: #000000;">??</div>''',
'      end,',
'      null',
'    ) within group (order by period)',
'    datas',
'  from',
'  (',
'    select',
'      ps.period,',
'      ps.country_id,',
'      d.cnt',
'    from',
'    (',
'      select period,country_id,count(id) cnt from DASH_PAYROLL_CYCLES group by period,country_id order by 2',
'    ) d,',
'    (',
'      select p.period, c.id country_id from DASH_PERIODS_V p, md_countries c where',
'            p.period > ''2016-11''',
'        and (:P520_REGION like ''%''||c.region||''%''  or trim(:P520_REGION) is null)',
'        and (:P520_HUB like ''%''||c.hub||''%'' or trim(:P520_HUB) is null)',
'        and (:P520_SUBREGION like ''%''||c.sub_region||''%'' or trim(:P520_SUBREGION) is null)',
'        and (c.id in (select * from  table(pcg.id_string_2_id_list(replace(:P520_COUNTRY,'':'','',''))) ) or  trim(:P520_COUNTRY) is null)',
'        and (:P520_PERIOD_YEAR like ''%''||trim(substr(p.period,1,4))||''%'' or trim(:P520_PERIOD_YEAR) is null)',
'        and (:P520_PERIOD_MONTH like ''%''||trim(substr(p.period,6,2))||''%'' or trim(:P520_PERIOD_MONTH) is null)',
'        and (c.region = :G_USER_REGION or :G_USER_REGION = ''GLOBAL'')',
'        and c.region is not null',
'    ) ps',
'    where ps.country_id = d.country_id (+) and ps.period = d.period (+)',
'  ) group by country_id',
') order by',
'case when nvl(pcg.get_country_region(country_id),''GLOBAL'') = ''GLOBAL'' then ''0'' end||',
'pcg.get_country_region(country_id)||',
'pcg.get_country_hub(country_id)||',
'pcg.get_country_subregion(country_id)||',
'pcg.get_country_name_branch(country_id)'))
,p_plug_source_type=>'NATIVE_IG'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_plug_display_condition_type=>'NEVER'
,p_plug_read_only_when_type=>'ALWAYS'
);
